negativeExample:
package test;

import org.eclipse.jface.preference.IPreferenceStore;
import org.eclipse.ui.texteditor.AbstractDecoratedTextEditorPreferenceConstants;
import org.eclipse.jface.dialogs.MessageDialogWithToggle;

public class TestClass {
    public void setup(IPreferenceStore store) {
        // Different preference key
        store.setDefault("some.other.preference", "");
        // Already using the target value
        store.setDefault(AbstractDecoratedTextEditorPreferenceConstants.REVISION_ASK_BEFORE_QUICKDIFF_SWITCH, MessageDialogWithToggle.ALWAYS);
    }
}
